"""Blue-and-white teacher workspace for one authenticated upload task."""

from .demo2_course_overview import OVERVIEW_CSS, OVERVIEW_JS
from .demo2_ui_kit import header_for, inject_kit


def render_course_analysis(account=None):
    # Teachers and company admins share this page; the header follows the role.
    header = header_for(account, "upload", admin_active="tasks", page="analysis", logout_bound=False)
    # 「课程总览」 is the first tab; its renderer is shared with /demo2/course-overview.
    html = HTML.replace("/*__OVERVIEW_CSS__*/", OVERVIEW_CSS, 1).replace("/*__OVERVIEW_JS__*/", OVERVIEW_JS, 1)
    return inject_kit(html, header=header, page="analysis")


